	}
	if err := os.Mkdir(target+"\\child", 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.Mkdir("literal", 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile("literal/report-1.svg", []byte("unrelated image"), 0o644); err != nil {
		t.Fatal(err)
	}
	markdownSymlink(t, target, "linked")
	if err := os.WriteFile("linked/native.svg", []byte("native"), 0o644); err != nil {
		t.Fatal(err)
	}
	requireMarkdownText(t, target+"\\native.svg", "native")
}

func TestMarkdownWindowsFinalNamesAndLinks(t *testing.T) {
	for _, suffix := range []string{".", " "} {
		t.Run(map[string]string{".": "dot", " ": "space"}[suffix], func(t *testing.T) {
			base := markdownWindowsDirectory(t)
			literal := base + "\\image.svg" + suffix
			if err := commitMarkdownOutputs([]markdownOutput{{path: "image.svg" + suffix, data: []byte("ordinary")}}); err != nil {
				t.Fatal(err)
			}
			requireMarkdownText(t, base+"\\image.svg", "ordinary")
			if err := commitMarkdownOutputs([]markdownOutput{{path: literal, data: []byte("literal")}}); err != nil {
				t.Fatal(err)
			}
			requireMarkdownText(t, literal, "literal")
			requireMarkdownText(t, base+"\\image.svg", "ordinary")
		})
	}
}

func TestMarkdownWindowsFinalLinkIsReplaced(t *testing.T) {
	base := markdownWindowsDirectory(t)
	sentinel := filepath.Join(base, "sentinel")
	if err := os.WriteFile(sentinel, []byte("untouched"), 0o644); err != nil {
		t.Fatal(err)
	}
	markdownSymlink(t, sentinel, "image.svg")
	if err := commitMarkdownOutputs([]markdownOutput{{path: "image.svg", data: []byte("replacement")}}); err != nil {
		t.Fatal(err)
	}
	requireMarkdownText(t, sentinel, "untouched")
	requireMarkdownText(t, "image.svg", "replacement")
	info, err := os.Lstat("image.svg")
	if err != nil || !info.Mode().IsRegular() {
		t.Fatalf("final entry was followed instead of replaced: %v, %v", info, err)
	}
}

func TestMarkdownWindowsNamespaceNormalization(t *testing.T) {
	for _, tc := range []struct {
		name, prefix, operand, actual, url string
	}{
		{"ordinary-dot-final", "", "assets.", "assets", "assets"},
		{"ordinary-dot-intermediate", "", "assets.\\child", "assets\\child", "assets/child"},
		{"ordinary-space-final", "", "assets ", "assets", "assets"},
		{"ordinary-space-intermediate", "", "assets \\child", "assets \\child", "assets%20/child"},
		{"device-dot-final", "\\\\.\\", "assets.", "assets", "assets"},
		{"device-dot-intermediate", "\\\\.\\", "assets.\\child", "assets\\child", "assets/child"},
		{"device-space-final", "\\\\.\\", "assets ", "assets", "assets"},
		{"device-space-intermediate", "\\\\.\\", "assets \\child", "assets \\child", "assets%20/child"},
		{"verbatim-dot-final", "\\\\?\\", "assets.", "assets.", "assets."},
		{"verbatim-dot-intermediate", "\\\\?\\", "assets.\\child", "assets.\\child", "assets./child"},
		{"verbatim-space-final", "\\\\?\\", "assets ", "assets ", "assets%20"},
		{"verbatim-space-intermediate", "\\\\?\\", "assets \\child", "assets \\child", "assets%20/child"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			base := markdownWindowsDirectory(t)
			for _, name := range []string{"assets", "assets.", "assets "} {
				if err := os.Mkdir(base+"\\"+name, 0o755); err != nil {
					t.Fatal(err)
				}
				if err := os.Mkdir(base+"\\"+name+"\\child", 0o755); err != nil {
					t.Fatal(err)
				}
			}
			root := strings.TrimPrefix(base, "\\\\?\\")
			if tc.prefix == "" && strings.HasPrefix(root, "UNC\\") {
				root = "\\\\" + root[len("UNC\\"):]
			}
			operand := tc.prefix + root + "\\" + tc.operand
			resolved, err := resolvedOutputDirectory(operand)
			if err != nil {
				t.Fatal(err)
			}
			actual, err := os.Stat(resolved)
			if err != nil {
				t.Fatal(err)
			}
			expected, err := os.Stat(base + "\\" + tc.actual)
			if err != nil {
				t.Fatal(err)
			}
			if !os.SameFile(actual, expected) {
				t.Fatalf("directory identity for %q: got %q, want %q", operand, resolved, tc.actual)
			}
			requireMarkdownSuccess(t, "render", "input.md", "-o", "report.md", "-a", operand)
			requireMarkdownText(t, "report.md", "![diagram]("+tc.url+"/report-1.svg)\n")
			requireMarkdownWindowsImage(t, base+"\\"+tc.actual+"\\report-1.svg")
		})
	}
}

package cli

import (
	"bytes"
	"errors"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"syscall"

	"github.com/gosuda/elegant-mermaid/internal/fileerr"
	"github.com/gosuda/elegant-mermaid/internal/markdown"
)

type markdownOutput struct {
	path string
	data []byte
}

func writeMarkdownOutputs(input string, raw []byte, blocks []markdown.Block, artifacts []markdownArtifact, o commandOptions) error {
	if err := validateMarkdownOutputPath(o.output, !o.artifactsSet || markdownHost(o.output)); err != nil {
		return err
	}
	paths := markdownArtifactPaths(input, o, len(artifacts))
	outputs := make([]markdownOutput, 0, len(artifacts)+1)
	for i, artifact := range artifacts {
		outputs = append(outputs, markdownOutput{path: paths[i], data: artifact.data})
	}
	if markdownHost(o.output) {
		data, err := rewriteMarkdown(raw, blocks, artifacts, paths, o.output)
		if err != nil {
			return err
		}
		outputs = append(outputs, markdownOutput{path: o.output, data: data})
	}
	return commitMarkdownOutputs(outputs)
}

func validateMarkdownOutputPath(path string, inspect bool) error {
	if path == "" {
		return nil
	}
	if err := validateMarkdownOutputName(path); err != nil {
		return err
	}
	if !inspect {
		return nil
	}
	info, err := os.Lstat(path)
	if err == nil && info.IsDir() {
		return fileerr.Write(path, syscall.EISDIR)
	}
	if err != nil && !errors.Is(err, os.ErrNotExist) {
		return fileerr.Write(path, err)
	}
	return nil
}

// The caller has excluded the empty, unspecified output operand.
func validateMarkdownOutputName(path string) error {
	base := filepath.Base(path)
	if base == "." || base == ".." || os.IsPathSeparator(path[len(path)-1]) {
		return fileerr.Write(path, syscall.EISDIR)
	}
	return nil
}

func markdownArtifactPaths(input string, o commandOptions, count int) []string {
	name := o.output
	if name == "" {
		name = input
	}
	stem, ext := markdownStem(filepath.Base(name))
	directory := outputDirectory(o.output)
	if o.output == "" || markdownHost(o.output) {
		ext = "." + markdownFormatExtension(o.format)
	}
	if markdownHost(o.output) {
		directory = joinOutputPath(outputDirectory(o.output), stem+".assets")
	}
	if o.artifactsSet {
		directory = o.artifacts
	}
	paths := make([]string, count)
	for i := range paths {
		paths[i] = joinOutputPath(directory, stem+"-"+strconv.Itoa(i+1)+ext)
	}
	return paths
}

func markdownStem(name string) (string, string) {
	ext := filepath.Ext(name)
	if ext == name {
		return name, ""
	}
	return strings.TrimSuffix(name, ext), ext
}

func markdownFormatExtension(format string) string {
	if format == "text" {
		return "txt"
	}
	return format
}

// Commit through the resolved filesystem directory: a missing prefix that ..
// cancels must not be created, and a later symlink keeps its meaning. MkdirAll
// on the lexical path fails where a symlink component meets .. (Lstat is not Stat).
func commitMarkdownOutputs(outputs []markdownOutput) error {
	resolved := make([]markdownOutput, 0, len(outputs))
	for _, output := range outputs {
		target, err := resolvedOutputTarget(output.path)
		if err != nil {
			return fileerr.Write(output.path, err)
		}
		resolved = append(resolved, markdownOutput{path: target, data: output.data})
	}
	for i, output := range resolved {
		if err := os.MkdirAll(outputDirectory(output.path), 0o755); err != nil {
			return fileerr.Write(outputs[i].path, err)
		}
	}
	for i, output := range resolved {
		if err := atomicOutput(output.path, output.data); err != nil {
			return fileerr.Write(outputs[i].path, err)
		}
	}
	return nil
}

// The scanner's raw spans are replaced in declaration order. All bytes in the
// gaps are copied verbatim, including invalid UTF-8 and mixed line endings.
func rewriteMarkdown(raw []byte, blocks []markdown.Block, artifacts []markdownArtifact, paths []string, output string) ([]byte, error) {
	text := make([]byte, 0, len(raw))
	previous := 0
	for i, block := range blocks {
		link, err := markdownRelativeLink(output, paths[i])
		if err != nil {
			return nil, fileerr.Write(output, err)
		}
		text = append(text, raw[previous:block.Span.Start]...)
		text = append(text, markdownOpenerPrefix(raw, block)...)
		text = append(text, "!["...)
		text = append(text, markdownAltText(artifacts[i].title)...)
		text = append(text, "]("...)
		text = append(text, link...)
		text = append(text, ')')
		text = append(text, markdownBlockEnding(raw, block)...)
		previous = block.Span.End
	}
	return append(text, raw[previous:]...), nil
}

func markdownOpenerPrefix(raw []byte, block markdown.Block) []byte {
	text := raw[block.Span.Start:block.Span.End]
	// A scanner-produced opener has a fence marker, and its container prefix
	// contains none of these bytes.
	return text[:bytes.IndexAny(text, "`~:")]
}

func markdownBlockEnding(raw []byte, block markdown.Block) []byte {
	end := block.Span.End
	if end == block.Span.Start {
		return nil
	}
	switch raw[end-1] {
	case '\r':
		return raw[end-1 : end]
	case '\n':
		start := end - 1
		if start > block.Span.Start && raw[start-1] == '\r' {
			start--
		}
		return raw[start:end]
	default:
		return nil
	}
}

func markdownAltText(title string) string {
	if title == "" {
		return "diagram"
	}
	var text strings.Builder
	for _, b := range []byte(title) {
		switch b {
		case '\r':
			text.WriteString("&#13;")
		case '\n':
			text.WriteString("&#10;")
		default:
			if strings.ContainsRune("!\"#$%&'()*+,-./:;<=>?@[\\]^_`{|}~", rune(b)) {
				text.WriteByte('\\')
			}
			text.WriteByte(b)
		}
	}
	return text.String()
}

func markdownRelativeLink(host, artifact string) (string, error) {
	directory, err := resolvedOutputDirectory(outputDirectory(host))
	if err != nil {
		return "", err
	}
	target, err := resolvedOutputTarget(artifact)
	if err != nil {
		return "", err
	}
	relative, err := filepath.Rel(directory, target)
	if err != nil {
		return "", err
	}
	return markdownLinkPath(filepath.ToSlash(relative)), nil
}

func markdownLinkPath(path string) string {
	const hex = "0123456789ABCDEF"
	var text strings.Builder
	for _, b := range []byte(path) {
		if markdownURLByte(b) {
			text.WriteByte(b)
			continue
		}
		text.WriteByte('%')
		text.WriteByte(hex[b>>4])
		text.WriteByte(hex[b&15])
	}
	return text.String()
}

func markdownURLByte(b byte) bool {
	return b >= 'a' && b <= 'z' || b >= 'A' && b <= 'Z' || b >= '0' && b <= '9' || strings.ContainsRune("-._~/", rune(b))
}

package tui

import (
	"os"
	"strings"
	"time"

	console "github.com/charmbracelet/x/windows"
	"golang.org/x/sys/windows"
)

type windowsInput struct{ handle windows.Handle }

func newTerminalInput(file *os.File) (terminalInput, error) {
	handle := windows.Handle(file.Fd())
	var mode uint32
	if err := windows.GetConsoleMode(handle, &mode); err != nil {
		return nil, err
	}
	return windowsInput{handle: handle}, nil
}

func (windowsInput) Close() error { return nil }

func (input windowsInput) Read(delay time.Duration) ([]byte, error) {
	deadline := time.Now().Add(delay)
	for time.Now().Before(deadline) {
		wait := max(0, int((time.Until(deadline)+time.Millisecond-1)/time.Millisecond))
		event, err := windows.WaitForSingleObject(input.handle, uint32(wait))
		if err != nil {
			return nil, err
		}
		if event == uint32(windows.WAIT_TIMEOUT) {
			return nil, nil
		}
		var record console.InputRecord
		var count uint32
		if err = console.PeekConsoleInput(input.handle, &record, 1, &count); err != nil {
			return nil, err
		}
		if count == 0 {
			continue
		}
		if err = console.ReadConsoleInput(input.handle, &record, 1, &count); err != nil {
			return nil, err
		}
		if count == 0 || record.EventType != 1 {
			continue
		}
		key := record.KeyEvent()
		if !key.KeyDown {
			continue
		}
		text := consoleKey(key)
		return []byte(strings.Repeat(text, int(key.RepeatCount))), nil
	}
	return nil, nil
}

func consoleKey(key console.KeyEventRecord) string {
	if key.Char != 0 {
		return string(key.Char)
	}
	switch key.VirtualKeyCode {
	case 0x25:
		return "\x1b[D"
	case 0x26:
		return "\x1b[A"
	case 0x27:
		return "\x1b[C"
	case 0x28:
		return "\x1b[B"
	}
	return ""
}
